/**
 * Härmälä as Infinite drew it in Claude Design (BRDC-WORLD-001).
 *
 * `seed/harmala.design-terrain.json` is generated by `scripts/gen-harmala.mjs` from the
 * design's own hex grid, shifted onto the real Statue of the Boy: one row per H3 res-10
 * parent, its seven res-11 children's terrain as letters in `cellToChildren` order ('.' =
 * the design did not reach that hex). Outside the drawn area this answers null, and the
 * rest of the terrain chain decides as before.
 *
 * Off by default, on at the app's boot (`createRepository`) — the same shape as
 * `enableWorldseed`: the core test suite plays in Härmälä's own coordinates, and its
 * economy tests must not depend on which hex the design calls a lake.
 */
import { cellToChildren, cellToParent, getResolution } from 'h3-js';
import design from './seed/harmala.design-terrain.json' with { type: 'json' };
import type { H3Index, Terrain, TerrainKind } from '../types/domain.js';

const KIND = Object.fromEntries(Object.entries(design.letters).map(([kind, letter]) => [letter, kind])) as Record<string, TerrainKind>;
const ROWS = design.rows as Readonly<Record<string, string>>;

let enabled = false;

/** Turn the designed Härmälä on (the app, at boot) or off (tests). */
export function enableDesignedTerrain(on = true): void {
  enabled = on;
}

/** The designed terrain of a res-11 hex, or null outside the drawn area. */
export function designedTerrainOf(h3: H3Index): Terrain | null {
  if (!enabled || getResolution(h3) !== 11) return null;
  const parent = cellToParent(h3, 10);
  const row = ROWS[parent];
  if (!row) return null;
  const kind = KIND[row[cellToChildren(parent, 11).indexOf(h3)] ?? '.'];
  return kind ? { kind, source: 'seed' } : null;
}
